class UseCase(BaseModel):
    """
    A use case is three artifacts -- a stored workflow component, the skill prompts its agent
    steps carry, and a spec record holding what the author asked for. This is the catalog view
    over all three. `level` is the autonomy level the activation screen shows; activating at
    three or above needs the admin role (G11).

    """

    id: str
    title: str
    description: str
    business_area: str = Field(
        ...,
        description="A business area identifier. In 1.0.0 this is the shipped `business_area` vocabulary\n(`egpt_retail/ontology/vocabularies.json`) plus whatever a customer overlay adds, so it is\na string validated at runtime against the deployment's vocabulary, not an enum.\n",
        examples=["inventory", "sales", "supply_chain"],
    )
    subject_area: str | None = ""
    tier: KpiLevel | None = None
    status: UseCaseStatus
    source: UseCaseSource
    level: int = Field(..., ge=1, le=5)
    autonomy: Autonomy
    tags: list[str] | None = None
    sample_question: str | None = ""
    supporting_questions: list[str] | None = None
    process_id: str | None = None
    linked_kpi_ids: list[str] | None = None
    workflow_component_id: str | None = Field(
        None,
        description="The framework component (`/components`) holding the compiled workflow, once one exists.",
    )
    version: int = Field(
        ...,
        description="Bumped on publish. Runs and golden sets are attributed to a version (R15).",
    )
    gallery_order: int | None = None
    last_run: UseCaseRunSummary | None = None
    updated_at: AwareDatetime = Field(..., description="RFC 3339, always UTC.")


class UseCaseDraft(BaseModel):
    """
    The builder's working state, steps one to nine. Persisted as a whole because the wizard
    reads and writes it as a whole. Steps four and five (`plan_items`, `tasks`) are deliberately
    absent: they are derived views served by `GET /use-cases/{id}/plan` over the compiled
    workflow, never authored here -- a plan authored in parallel with the workflow is the
    failure the build plan names.

    """

    version: int
    step1: DraftStep1
    step2: DraftStep2
    step3: DraftStep3
    step6: DraftStep6 | None = None
    step7: DraftStep7 | None = None
    step8: DraftStep8
    step9: DraftStep9 | None = None
    updated_at: AwareDatetime | None = Field(None, description="RFC 3339, always UTC.")


